let problems = 0;
const once = (s, a) => s.split(a).length === 2;
const read = (file) => { const p = path.join(root, file); return fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null; };
function edit(file, what, done, change) {
  const s = read(file);
  if (s === null) { console.log(`MISSING   ${file}: not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; return; }
  if (s.replace(/\r\n/g, '\n').includes(done)) { console.log(`already   ${file}: ${what}`); return; }
  const eol = s.includes('\r\n') ? '\r\n' : '\n';
  const out = change(s.replace(/\r\n/g, '\n'));
  if (typeof out !== 'string') { console.log(`REFUSED   ${file}: ${out && out.why ? out.why : 'its text is not what this patch expects'}, so nothing was changed. Send this file.`); problems++; return; }
  plan.push({ file, what, before: s, after: out.replace(/\n/g, eol) });
}

for (const e of DATA.created) {
  const p = path.join(root, e.file);
  if (fs.existsSync(p)) {
    if (fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n') === e.text) { console.log(`already   ${e.file}: ${e.what}`); continue; }
    console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
  }
  // a new folder (services/api/src/modules/profits) is made, but only inside one that is already there
  if (!fs.existsSync(path.dirname(path.dirname(p)))) { console.log(`MISSING   ${path.dirname(path.dirname(e.file))}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
  plan.push({ file: e.file, what: e.what, before: null, after: e.text });
}
for (const e of DATA.anchored) {
  edit(e.file, e.what, e.done, (s) => {
    let out = s;
    for (const [a, b] of e.pairs) { if (!once(out, a)) return null; out = out.replace(a, () => b); }
    return out;
  });
}
edit('services/api/src/index.js', 'server: /parcel-costs is served', "require('./modules/parcelCosts/routes')", (s) => {
  const m = s.match(/\n([ \t]*)app\.use\('\/payouts', payoutsRoutes\);[^\n]*/);
  if (!m) return { why: "the line app.use('/payouts', payoutsRoutes); was not found" };
  const at = m.index + m[0].length;
  return s.slice(0, at) + `\n${m[1]}app.use('/parcel-costs', require('./modules/parcelCosts/routes')); // parcel shipping costs (migration 127)` + s.slice(at);
});
edit('services/api/src/modules/hub/routes.js', 'server: a parcel ships only once its shipping cost is recorded (and approved when dearer)', "parcelCosts.shipCheck(", (s) => {
  const req = "const deliveryProof = require('../deliveryProof/helpers');\n";
  const at = "    const shipment = shipCheck.rows[0];\n\n    let returnNotifications = [];\n";
  if (!once(s, req)) return { why: 'the deliveryProof require was not found' };
  if (!once(s, at)) return { why: 'the start of the hub step route was not found' };
  return s.replace(req, () => req + "const parcelCosts = require('../parcelCosts/service');      // the Shipping cost step (migration 127)\n")
    .replace(at, () => `    const shipment = shipCheck.rows[0];

    // The parcel's real shipping cost (migration 127) must be recorded -- and, when it is dearer than planned, approved by an admin -- before it ships.
    if (step === 'shipped_to_buyer') {
      const cost = await parcelCosts.shipCheck(client, shipment.id);
      if (!cost.allowed) {
        await client.query('ROLLBACK');
        return res.status(409).json({ error: cost.error, code: cost.code });
      }
    }

    let returnNotifications = [];
`);
});
edit('services/api/src/modules/order/routes.js', 'server, checkout: each order line keeps the shipping inside its price', 'shipping_planned_usd', (s) => {
  const a = '    const buyerUnitPrices = {};\n';
  const b = '        totalShippingPortionUsd += shippingCny * result.fxRate * quantity;\n';
  const c = "          `INSERT INTO order_line_items (sub_order_id, product_id, quantity, unit_price, supplier_unit_price_cny) VALUES ($1, $2, $3, $4, $5)`,\n          [subOrderId, item.productId, item.quantity, buyerUnitPrices[item.productId], supplierUnitPriceCny(productById[item.productId])]\n";
  if (!once(s, a) || !once(s, b) || !once(s, c)) return { why: 'the checkout pricing or the order line insert was not found' };
  return s.replace(a, () => a + '    const shippingPlannedUnitUsd = {};   // the shipping inside ONE unit\'s price (migration 127): compared later with what the hub really pays\n')
    .replace(b, () => b + '        shippingPlannedUnitUsd[productId] = shippingCny * result.fxRate;\n')
    .replace(c, () => "          `INSERT INTO order_line_items (sub_order_id, product_id, quantity, unit_price, supplier_unit_price_cny, shipping_planned_usd) VALUES ($1, $2, $3, $4, $5, $6)`,\n          [subOrderId, item.productId, item.quantity, buyerUnitPrices[item.productId], supplierUnitPriceCny(productById[item.productId]), shippingPlannedUnitUsd[item.productId] ?? null]\n");
});
edit('services/api/src/modules/overview/routes.js', 'server: the admin bell counts the parcels waiting for approval', 'shippingCostsWaiting', (s) => {
  const a = '      openTickets: Number(openTickets.rows[0].n),\n';
  if (!once(s, a)) return { why: 'the openTickets count was not found' };
  return s.replace(a, () => a + "      shippingCostsWaiting: await require('../parcelCosts/service').waitingCount(db),      // parcels waiting for approval (migration 127)\n");
});
edit('apps/admin-dashboard/src/adminNav.js', 'admin: Shipping costs is a tab of Financial, after Profits', "'shippingCosts'", (s) => {
  if (!once(s, "'pricing', 'profits'")) return { why: "the Financial group with 'profits' was not found (run patch-profits.js first)" };
  if (!once(s, "profits: 'Profits',")) return { why: "the tab name profits: 'Profits' was not found" };
  return s.replace("'pricing', 'profits'", () => "'pricing', 'profits', 'shippingCosts'").replace("profits: 'Profits',", () => "profits: 'Profits', shippingCosts: 'Shipping costs',");
});
if (read('apps/admin-dashboard/src/adminNav.test.js') !== null) edit('apps/admin-dashboard/src/adminNav.test.js', 'admin: menu test (Financial now has Shipping costs)', "'profits', 'shippingCosts']]", (s) => {
  const t = "'pricing', 'profits']],";
  if (!once(s, t)) return { why: 'the Financial line of the test was not found' };
  return s.replace(t, () => "'pricing', 'profits', 'shippingCosts']],");
});
edit('apps/admin-dashboard/src/App.jsx', 'admin: the Shipping costs page, and the bell', 'import ShippingCostsPanel from "./ShippingCostsPanel";', (s) => {
  const imp = s.match(/\nimport ProfitsPanel from "\.\/ProfitsPanel";[^\n]*/);
  if (!imp) return { why: 'the ProfitsPanel import was not found (run patch-profits.js first)' };
  let out = s.slice(0, imp.index + imp[0].length) + '\nimport ShippingCostsPanel from "./ShippingCostsPanel";      // Financial -> Shipping costs (migration 127)' + s.slice(imp.index + imp[0].length);
  if (!/[{,]\s*Truck\s*[,}]/.test(out.slice(0, out.indexOf('const NAV')))) return { why: 'the Truck icon is not imported' };
  const nav = out.match(/\n([ \t]*)\{ id: "profits", label: "Profits", icon: TrendingUp \},[^\n]*/);
  if (!nav) return { why: 'the Profits entry of the menu list was not found' };
  out = out.slice(0, nav.index + nav[0].length) + `\n${nav[1]}{ id: "shippingCosts", label: "Shipping costs", icon: Truck },` + out.slice(nav.index + nav[0].length);
  const page = out.match(/\n([ \t]*)else if \(page === "profits"\) content = [^\n]*/);
  if (!page) return { why: 'the line that opens the Profits page was not found' };
  out = out.slice(0, page.index + page[0].length) + `\n${page[1]}else if (page === "shippingCosts") content = <div><TopBar title="Shipping costs" subtitle="What every parcel really cost to ship, as the hubs entered it, against the shipping inside its prices. Only admins see these amounts." /><ShippingCostsPanel onSessionExpired={onLogout} /></div>;` + out.slice(page.index + page[0].length);
  // the bell: the parcels waiting for approval
  const zero = 'openTickets: 0 }';
  if (out.split(zero).length !== 3) return { why: 'the two empty bell counts were not found' };
  out = out.split(zero).join('openTickets: 0, shippingCostsWaiting: 0 }');
  const fill = 'openTickets: data.openTickets';
  if (out.split(fill).length < 2) return { why: 'the bell counts from GET /overview were not found' };
  out = out.split(fill).join('openTickets: data.openTickets, shippingCostsWaiting: data.shippingCostsWaiting || 0');
  const total = 'counts.openTickets + flaggedCount;';
  const item = '    { count: flaggedCount, label: "Flagged shipments", page: "flagged" },\n';
  if (!once(out, total) || !once(out, item)) return { why: 'the bell total or its list was not found' };
  return out.replace(total, () => 'counts.openTickets + flaggedCount + (counts.shippingCostsWaiting || 0);')
    .replace(item, () => item + '    { count: counts.shippingCostsWaiting || 0, label: "Shipping costs to approve", page: "shippingCosts" },\n');
});

if (problems > 0) { console.log('\nNothing was changed, because of the problem(s) above.'); process.exit(1); }
for (const c of plan) {
  if (write) {
    const p = path.join(root, c.file);
    if (c.before !== null) fs.writeFileSync(`${p}.before-parcel-costs`, c.before);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, c.after);
    console.log(`${c.before === null ? 'created ' : 'patched '}  ${c.file}: ${c.what}`);
  } else console.log(`would     ${c.file}: ${c.what}`);
}
if (!write && plan.length) console.log('\nDry run only. Add --write to apply.');
if (write && plan.length) console.log('\nDone. Then: cd services\\api ; npm run migrate ; restart the API. Admin portal and hub portal: Ctrl+F5. Hub app: q, then flutter run.');
